leach.pseudocode:
def leach_setup(nodes, P, r):
    # P: 원하는 헤드 비율, r: 현재 라운드 번호
    epoch = round(1 / P)
    if r % epoch == 0:  # 새 에폭: 모두 후보 복귀
        for n in nodes:
            n.eligible = True
    T = P / (1 - P * (r % epoch))  # 선출 임계값
    heads = []
    for n in nodes:
        if n.eligible and random() < T:
            n.eligible = False  # 에폭 내 재선출 금지
            heads.append(n)
    for n in nodes:  # 비헤드는 가장 가까운 헤드에 가입
        if n not in heads and heads:
            n.head = min(heads, key=lambda h: dist(n, h))
    return heads

leaderless-replication.pseudocode:
def quorum_write(key, val, ver, replicas, W):
    acks = 0
    for node in replicas:  # N개 모두에 전송(병렬 가정)
        if node.try_put(key, val, ver):
            acks += 1
    return acks >= W  # W개 이상 성공해야 완료

def quorum_read(key, replicas, R):
    resps = []
    for node in replicas:
        r = node.try_get(key)
        if r is not None:
            resps.append((node, r))
        if len(resps) == R:  # R개 응답이면 충분
            break
    if len(resps) < R:
        raise QuorumError()
    latest = max((r for _, r in resps), key=lambda r: r.ver)
    for node, r in resps:
        if r.ver < latest.ver:  # 낡은 복제본 → 읽기 복구
            node.try_put(key, latest.val, latest.ver)
    return latest.val

least-connection.pseudocode:
active = {'s1': 0, 's2': 0, 's3': 0}  # 서버별 활성 연결 수
weight = {'s1': 1, 's2': 2, 's3': 1}  # 처리 능력 가중치

def pick_server():
    # 가중 최소 연결: 연결 수 / 가중치가 가장 작은 서버
    return min(active, key=lambda s: active[s] / weight[s])

def on_request(req):
    s = pick_server()
    active[s] += 1  # 연결 시작
    try:
        return forward(s, req)
    finally:
        active[s] -= 1  # 연결 종료 시 감소

least-significant-bit.pseudocode:
def lsb_embed(pixels, bits):
    if len(bits) > len(pixels):
        raise ValueError('용량 초과')  # 픽셀당 1비트
    out = list(pixels)
    for i, b in enumerate(bits):
        out[i] = (out[i] & ~1) | b  # 최하위 비트만 교체
    return out

def lsb_extract(pixels, n_bits):
    return [p & 1 for p in pixels[:n_bits]]
